#!/bin/bash
# Build guide Step 5: LFS 13.1-systemd chapter 8, the final system, run INSIDE the chroot as root.
# GENERATED by gen.py from the book's pages: each pkg_* body is the book's commands verbatim, except
# lines marked "[skipped]" (optional docs, upgrade-only, interactive) and the documented replacements.
# Started by ch7-chroot.sh with INSIDE=ch8-inside.sh. Never run it on the host.
set -euo pipefail

# Refuse to run on the host: /sources only exists inside the chroot, and the host is Ubuntu.
if [ ! -e /sources/wget-list-systemd ] || grep -qi ubuntu /etc/os-release 2>/dev/null; then
  echo "ch8-inside.sh: not inside the Autark chroot; refusing to run" >&2
  exit 1
fi

logs=/sources/logs
mkdir -p "$logs" /sources/.done /sources/.track /var/lib/autark/files
srcdir=/sources
source "$(dirname "$0")/build-lib.sh"

# Autark's build flags (decisions.md, "CPU target" and "Build hardening"): every package from here on.
# PIE comes from GCC's --enable-default-pie. glibc overrides these in its own function.
export CFLAGS="-O2 -march=x86-64-v3 -pipe -fstack-protector-strong -fstack-clash-protection -fcf-protection=full -D_FORTIFY_SOURCE=3"
export CXXFLAGS="$CFLAGS"
export LDFLAGS="-Wl,-O1 -Wl,-z,relro -Wl,-z,now"

# A failed test suite is recorded, not fatal (the book lists known failures); review test-failures.txt.
testfail() {
  echo "== TESTFAIL: $*"
  echo "$(date +%T) $*" >> "$logs/test-failures.txt"
}

# Package tracking (build guide Step 5.3, before/after snapshot): every file or symlink a package
# creates on the root filesystem is listed in /var/lib/autark/files/<package>.
snapshot() {
  find / -xdev \( -path /sources -o -path /tmp -o -path /root -o -path /var/lib/autark \) -prune \
    -o \( -type f -o -type l \) -print | LC_ALL=C sort
}

# Build one package once: skip if done, snapshot, build, record its new files, mark done.
run_pkg() {
  local name=$1 tarball=$2 fn=$3
  if [ -e "/sources/.done/ch8-$name" ]; then echo "== $name: already done, skipped"; return; fi
  snapshot > "/sources/.track/before"
  if [ "$tarball" = - ]; then
    echo "== $fn: started $(date +%T)"
    set +e; ( set -e; cd /sources; "$fn" ) > "$logs/$fn.log" 2>&1; local rc=$?; set -e
    if [ "$rc" != 0 ]; then echo "== $fn: FAILED (exit $rc)"; tail -25 "$logs/$fn.log"; exit 1; fi
    echo "== $fn: done"
  else
    build "$tarball" "$fn"
  fi
  snapshot | LC_ALL=C comm -13 /sources/.track/before - > "/var/lib/autark/files/$name"
  echo "   $(wc -l < "/var/lib/autark/files/$name") new files tracked"
  touch "/sources/.done/ch8-$name"
}

